    def _handle_params(self, products: tuple[str, ...]) -> None:
        with _sm() as msg:
            msg.write("## IC / IM 动量分袖研究候选 1.2 参数\n\n")
            msg.write(
                "共同结构：0.5倍持续裸滚核心袖 + 0.5×动量权重袖 + 0或1倍独立网格；"
                "动量权重只允许0/0.5/1。\n\n"
            )
            for product in products:
                if product == "IC":
                    msg.write("### IC 1.2（SC 查询别名）\n\n")
                    msg.write(
                        "- 动量：MA110 / Mom24 / W2；Score>0；50% OFF + 50% Abs20>0。\n"
                    )
                    msg.write("- 核心Put完整继承IC V2；动量袖Put只看估值，不使用MOM120下限。\n")
                    msg.write("- 网格：≤0.375 加1倍，≥1.000 退出；新增腿不配Put。\n")
                    msg.write("- IC不卖Call。\n\n")
                else:
                    msg.write("### IM 1.2\n\n")
                    msg.write(
                        "- 动量：MA35 / Mom18 / W2.5；Score>0；50% OFF + 50% Abs20>0。\n"
                    )
                    msg.write("- Put/Call只覆盖0.5倍核心袖；动量袖与网格均不配期权。\n")
                    msg.write("- IM父规则MOM120<0时最低3张；第4张只能由估值第4档产生。\n")
                    msg.write(
                        "- 网格：≤1.60 加1倍，≥2.00 退出；新增腿不加Put或Call。\n"
                    )
                    msg.write(
                        "- Call：D10、IV≥26%、5%威胁救援、`rescue_next_listed`、最多5次。\n\n"
                    )
            msg.write(
                "本版本是研究候选，不生成订单，也不是实盘授权。\n\n"
            )

    def _handle_performance(self, intent: QueryIntent) -> None:
        assert intent.start is not None and intent.end is not None
        with _sm() as msg:
            msg.write("## 1.2 历史表现尚未对外开放\n\n")
            msg.write(
                "1.2 当前只冻结了逐腿目标日程与审计，尚未把不同父规则、Put/Call和独立网格"
                "重新合成为可声明的正式组合绩效。为避免误用V2收益，本查询不会返回旧V2曲线。\n\n"
            )
        return
        with _sm() as msg:
            msg.write(
                f"## 历史表现：{intent.start} 至 {intent.end}\n\n"
            )
            for product in intent.products:
                try:
                    frame = performance_frame(
                        product, intent.start, intent.end, refresh_latest=True
                    )
                except (
                    ValueError,
                    RuntimeError,
                    requests.RequestException,
                    zipfile.BadZipFile,
                    KeyError,
                ) as exc:
                    msg.write(f"### {product}\n\n⚠️ {exc}\n\n")
                    continue
                metrics = performance_metrics(frame)
                actual_end = frame.index[-1].date()
                live_rows = int(frame["is_live"].sum())
                chart = render_nav_drawdown_chart(product, frame, intent.start)
                msg.write(f"### {PRODUCT_NAMES[product]}\n\n")
                benchmark_cn = "中证500价格指数" if product == "IC" else "中证1000价格指数"
                msg.attach_file(
                    name=f"{product.lower()}_nav_drawdown_{intent.start}_{actual_end}.png",
                    contents=chart,
                    content_type="image/png",
                    is_inline=True,
                )
                if live_rows:
                    msg.write(
                        f"数据已更新至 **{actual_end}**：{DATA_CUTOFF}及以前为使用真实历史期货、"
                        "期权和指数行情计算并哈希校验的正式回测段，"
                        f"其后 {live_rows} 个交易日按真实期货、期权和指数日行情续接。\n\n"
                    )
                else:
                    msg.write(f"本次区间数据截至 **{actual_end}**。\n\n")
                if actual_end < intent.end:
                    msg.write(
                        f"请求终点晚于当前可核验终点；{actual_end}之后涉及月度换仓状态重置，"
                        "未用假设持仓代替实际持仓。\n\n"
                    )
                msg.write(
                    f"区间收益 **{metrics['return']:.2%}**｜年化 **{metrics['cagr']:.2%}**｜"
                    f"年化波动 **{metrics['volatility']:.2%}**｜夏普 **{metrics['sharpe']:.2f}**｜"
                    f"最大回撤 **{metrics['max_drawdown']:.2%}**\n\n"
                )
                msg.write(
                    f"净值图已叠加 **{benchmark_cn}** 收盘价格曲线；两条曲线均按查询区间首日归一为1。\n\n"
                )
            msg.write(
                "绩效继承冻结研究口径：每1倍期货30%保证金/缓冲及剩余现金3%；未另行加入滑点、冲击、涨跌停未成交、容量、动态保证金上调和税费。\n\n"
            )


